    selected = [groups[i] is not None and 15 <= groups[i] <= 17 and en[i] is not None and en[i] >= 2.0 for i in range(n)]
    result = 0.0
    for edge in s.get('neighbors') or []:
        i = edge.get('i', -1)
        j = edge.get('j', -1)
        d = edge.get('distance_A')
        if 0 <= i < n and 0 <= j < n and d is not None and d > 0 and occ[i] > 0 and occ[j] > 0 and selected[i] and selected[j]:
            a = radii[i]
